+
+    configResolved(config: ResolvedConfig) {
+      sourcePath = resolveSourcePath(options.source, config.root)
+    },
+
+    buildStart() {
+      loadFlags()
+    },
+
+    resolveId(id) {
+      return id === virtualModuleId ? resolvedVirtualModuleId : undefined
+    },
+
+    load(id) {
+      if (id !== resolvedVirtualModuleId) {
+        return undefined
+      }
+
+      return createVirtualModule(loadFlags())
+    },
+
+    configureServer(devServer) {
+      server = devServer
+      devServer.watcher.add(sourcePath!)
+
+      const updateFlags = (changedPath: string): void => {
+        if (!isConfiguredSource(changedPath, sourcePath!)) {
+          return
+        }
+
+        try {
+          loadFlags()
+        } catch (error) {
+          reportWatchError(error)
+          return
+        }
+
+        const module = devServer.moduleGraph.getModuleById(resolvedVirtualModuleId)
+        if (module) {
+          devServer.moduleGraph.invalidateModule(module)
+        }
+        devServer.ws.send({ type: 'full-reload' })
+      }
+
+      devServer.watcher.on('change', updateFlags)
+      devServer.watcher.on('add', updateFlags)
+
+      return () => {
+        devServer.watcher.off('change', updateFlags)
+        devServer.watcher.off('add', updateFlags)
+        server = undefined
+      }
+    },
+
+    handleHotUpdate(context) {
+      if (!isConfiguredSource(context.file, sourcePath!)) {
+        return undefined
+      }
+
+      try {
